#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    vector<int> T(N);
    for (int i = 0; i < N; i++) {
        cin >> T[i];
    }

    vector<int> d(N);
    long long sum = 0;
    for (int i = 0; i < N; i++) {
        // Try both representations and pick the one with smaller absolute value
        int a = T[i];
        int b = T[i] - M;
        if (abs(a) < abs(b)) d[i] = a;
        else if (abs(b) < abs(a)) d[i] = b;
        else d[i] = a; // tie, pick positive
        sum += d[i];
    }

    // Adjust to make sum 0 mod M by changing one element's representation
    long long modsum = ((sum % M) + M) % M;
    if (modsum != 0) {
        // try to fix by switching one element to its other representation
        bool fixed = false;
        for (int i = 0; i < N && !fixed; i++) {
            int other = (T[i] - M);
            if (abs(other) < abs(d[i])) continue; // only if other is worse
            long long newsum = sum - d[i] + other;
            if ((newsum % M + M) % M == 0) {
                sum = newsum;
                d[i] = other;
                fixed = true;
            }
        }
        if (!fixed) {
            cout << -1 << '\n';
            return 0;
        }
    }

    long long pos = 0, neg = 0;
    for (int x : d) {
        if (x > 0) pos += x;
        else if (x < 0) neg += -x;
    }

    cout << max(pos, neg) << '\n';
    return 0;
}

