#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    vector<long long> T(N);
    for (int i = 0; i < N; ++i) cin >> T[i];

    // For each cylinder i, let xi be the net number of clockwise turns applied to it.
    // Then xi mod M must equal T[i].
    //
    // Each move changes two distinct cylinders by +1,+1 or -1,-1.
    // Therefore:
    // 1) Sum of all xi changes by +/-2 each move, so sum(xi) must be even.
    // 2) If we realize some integers xi with even sum, minimum moves = sum(|xi|)/2,
    //    because each move contributes 1 to |xi| on two cylinders.
    //
    // For each cylinder, xi can be T[i] + k*M for any integer k.
    // We want to minimize sum(|xi|) subject to total sum even.

    vector<long long> best(N), altCost(N, (long long)4e18);
    long long sumAbs = 0;
    long long sumXi = 0;

    for (int i = 0; i < N; ++i) {
        long long t = T[i];

        // Minimal absolute representative of t modulo M.
        // Candidates near 0 are:
        //   t
        //   t - M
        // (enough since t in [0, M-1])
        long long a = t;
        long long b = t - M;

        long long chosen;
        if (llabs(a) < llabs(b)) chosen = a;
        else if (llabs(b) < llabs(a)) chosen = b;
        else {
            // tie, choose either; parity handling done separately
            chosen = a;
        }

        best[i] = chosen;
        sumAbs += llabs(chosen);
        sumXi += chosen;

        // Compute minimal extra cost to flip parity of total sum using this cylinder.
        // Need another representative with opposite parity contribution.
        // If M is even, adding/subtracting M does not change parity, so impossible.
        // If M is odd, shifting by +/-M flips parity.
        if (M % 2 == 1) {
            long long c1 = chosen + M;
            long long c2 = chosen - M;
            long long extra = min(llabs(c1), llabs(c2)) - llabs(chosen);
            altCost[i] = extra;
        }
    }

    // Need even total sum.
    if ((sumXi & 1LL) != 0) {
        long long add = (long long)4e18;
        for (int i = 0; i < N; ++i) add = min(add, altCost[i]);
        if (add > (long long)3e18) {
            cout << -1 << '\n';
            return 0;
        }
        sumAbs += add;
    }

    // Also, with only one cylinder, no move is possible at all.
    if (N == 1) {
        if (T[0] == 0) cout << 0 << '\n';
        else cout << -1 << '\n';
        return 0;
    }

    cout << (sumAbs / 2) << '\n';
    return 0;
}

