int main() {
    int N, M;
    scanf("%d %d", &N, &M);
    int T[N];
    long long sum = 0;
    for (int i = 0; i < N; i++) {
        scanf("%d", &T[i]);
        T[i] %= M;
        sum += T[i];
    }
    if (sum % M != 0) {
        printf("-1\n");
        return 0;
    }

    long long forward = 0, backward = 0;
    for (int i = 0; i < N; i++) {
        int diff = T[i];
        if (diff <= M - diff) {
            forward += diff;
        } else {
            backward += M - diff;
        }
    }

    long long pairs = forward < backward ? forward : backward;
    long long leftover = llabs(forward - backward);
    long long turns = pairs + (leftover / 2) * M;
    printf("%lld\n", turns);
    return 0;
}

