static long long llabsll(long long x) { return x < 0 ? -x : x; }

int main(void) {
    int N;
    long long M;
    if (scanf("%d %lld", &N, &M) != 2) return 0;

    long long sumMin = 0;
    long long sumMax = 0;

    for (int i = 0; i < N; i++) {
        long long t;
        scanf("%lld", &t);

        long long cw = t;           // clockwise from 0 to t
        long long ccw = M - t;      // counterclockwise from 0 to t
        if (t == 0) ccw = 0;        // same position, no need to move

        long long mn = cw < ccw ? cw : ccw;
        long long mx = cw > ccw ? cw : ccw;

        sumMin += mn;
        sumMax += mx;
    }

    /* Each turn changes total signed movement by 2, so total must be even.
       We need to choose for each cylinder either cw or -ccw so that
       sum of chosen signed movements is 0.
       Let total chosen clockwise amount be S. Then:
         S - (totalAlt - S) = 0  =>  2S = totalAlt
       Equivalently, total number of individual cylinder-steps used must be even,
       and any total between sumMin and sumMax with same parity is achievable
       because each cylinder can be switched from mn to mx, changing by |M-2t|.
    */

    long long ans = -1;

    if ((sumMin & 1LL) == 0) {
        ans = sumMin / 2;
    } else {
        if (sumMin + 1 <= sumMax) {
            ans = (sumMin + 1) / 2;
        } else {
            ans = -1;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

import java.util.Scanner;

public class DialLock {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int[] T = new int[N];
        for (int i = 0; i < N; i++) {
            T[i] = sc.nextInt();
        }
        sc.close();

        // diff[i] = needed increment mod M
        long[] diff = new long[N];
        for (int i = 0; i < N; i++) {
            diff[i] = (T[i] % M + M) % M;
        }

        // We try all possible offsets for first element
        long answer = Long.MAX_VALUE;

        for (int firstChoice = 0; firstChoice < 2; firstChoice++) {
            long[] cur = diff.clone();
            long moves = 0;
            boolean possible = true;

            if (firstChoice == 1) {
                // turn cylinder 0 up by 1 and cylinder 1 down by 1 or vice versa?
                // Instead, we'll handle via loop below by trying both directions.
            }

            // We'll solve using greedy: scan from left to right
            long[] a = cur;
            for (int i = 0; i < N - 1; i++) {
                if (a[i] == 0) continue;
                long need = a[i];
                // apply need to i and i+1: increase i, decrease i+1
                a[i] = (a[i] - need + M) % M;
                a[i + 1] = (a[i + 1] - need + M) % M;
                moves += need;
            }
            if (a[N - 1] != 0) possible = false;
            if (possible) answer = Math.min(answer, moves);

            // Try opposite direction for first element
            a = cur.clone();
            moves = 0;
            // turn i up and i+1 down? Actually we can try turning first down and second up
            // The greedy above already tried "push forward". 
            // We need also to handle the circular nature: try adjusting first element with last.
        }

        // Since the lock is circular, we can solve by trying all possible offsets for diff[0] 
        // such that we reduce it to zero using diff[N-1].
        // Simpler: brute force the amount we transfer between first and last.
        for (long transfer = 0; transfer < M; transfer++) {
            long[] a = diff.clone();
            long moves = transfer;
            a[0] = (a[0] - transfer + M) % M;
            a[N - 1] = (a[N - 1] + transfer) % M;

            boolean ok = true;
            for (int i = 0; i < N - 1; i++) {
                long need = a[i];
                moves += need;
                a[i] = 0;
                a[i + 1] = (a[i + 1] - need + M) % M;
            }
            if (a[N - 1] != 0) ok = false;
            if (ok) answer = Math.min(answer, moves);
        }

        if (answer == Long.MAX_VALUE) {
            System.out.println(-1);
        } else {
            System.out.println(answer);
        }
    }
}

