        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int[] T = new int[N];
        for (int i = 0; i < N; i++) T[i] = sc.nextInt();

        long[] c = new long[N];
        long S = 0;
        for (int i = 0; i < N; i++) {
            c[i] = Math.min(T[i], M - T[i]);
            S += c[i];
        }

        if (S % 2 == 0) {
            System.out.println(S / 2);
        } else {
            if (M % 2 == 0) {
                System.out.println(-1);
            } else {
                long minExtra = Long.MAX_VALUE;
                for (int i = 0; i < N; i++) {
                    minExtra = Math.min(minExtra, M - 2 * c[i]);
                }
                System.out.println((S + minExtra) / 2);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        long sumMin = 0;
        long sumMax = 0;

        for (int i = 0; i < N; i++) {
            int t = fs.nextInt();
            int cw = t;                 // turns clockwise from 0 to t
            int ccw = (M - t) % M;      // turns counterclockwise from 0 to t

            int mn = Math.min(cw, ccw);
            int mx = Math.max(cw, ccw);

            sumMin += mn;
            sumMax += mx;
        }

        // In each move, total chosen "unit turns" changes by exactly 2.
        // So if total required turns is S, we need S even, and S must be achievable
        // by choosing for each cylinder either cw or ccw count.
        // All achievable totals form every integer in [sumMin, sumMax].
        // Thus answer is the smallest even S in that range, divided by 2.
        long S = sumMin;
        if ((S & 1L) == 1L) S++;

        if (S > sumMax) {
            System.out.println(-1);
        } else {
            System.out.println(S / 2);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
